import type { FactionId, UnitType } from '../../game/types';

const BASE_URL = (import.meta.env?.BASE_URL ?? '/').replace(/\/?$/, '/');
const spriteUrl = (file: string): string => `${BASE_URL}sprites/${file}`;

/**
 * Maps `${faction}_${unitType}` -> unified Polytopia-style flat-shaded SVG sprite URL.
 * All 24 faction × unit sprites are 512×512 bottom-anchored (y = 492) vector assets
 * generated by `scripts/generate_polytopia_sprites.mjs`.
 */
export const UNIT_SPRITE_URLS: Record<string, string> = {
  // Humans — 6 unified Polytopia SVGs
  humans_warrior: spriteUrl('humans_warrior.svg'),
  humans_defender: spriteUrl('humans_defender.svg'),
  humans_archer: spriteUrl('humans_archer.svg'),
  humans_rider: spriteUrl('humans_rider.svg'),
  humans_catapult: spriteUrl('humans_catapult.svg'),
  humans_rohirrim_knight: spriteUrl('humans_rohirrim_knight.svg'),

  // Orcs — 6 unified Polytopia SVGs
  orcs_warrior: spriteUrl('orcs_warrior.svg'),
  orcs_defender: spriteUrl('orcs_defender.svg'),
  orcs_archer: spriteUrl('orcs_archer.svg'),
  orcs_rider: spriteUrl('orcs_rider.svg'),
  orcs_catapult: spriteUrl('orcs_catapult.svg'),
  orcs_uruk_berserker: spriteUrl('orcs_uruk_berserker.svg'),

  // Elves — 6 unified Polytopia SVGs
  elves_warrior: spriteUrl('elves_warrior.svg'),
  elves_defender: spriteUrl('elves_defender.svg'),
  elves_archer: spriteUrl('elves_archer.svg'),
  elves_rider: spriteUrl('elves_rider.svg'),
  elves_catapult: spriteUrl('elves_catapult.svg'),
  elves_elven_sentinel: spriteUrl('elves_elven_sentinel.svg'),

  // Dwarves — 6 unified Polytopia SVGs
  dwarves_warrior: spriteUrl('dwarves_warrior.svg'),
  dwarves_defender: spriteUrl('dwarves_defender.svg'),
  dwarves_archer: spriteUrl('dwarves_archer.svg'),
  dwarves_rider: spriteUrl('dwarves_rider.svg'),
  dwarves_catapult: spriteUrl('dwarves_catapult.svg'),
  dwarves_ironbreaker: spriteUrl('dwarves_ironbreaker.svg'),
};

const UNIQUE_UNIT_FALLBACKS: Partial<Record<UnitType, string>> = {
  rohirrim_knight: UNIT_SPRITE_URLS.humans_rohirrim_knight,
  uruk_berserker: UNIT_SPRITE_URLS.orcs_uruk_berserker,
  elven_sentinel: UNIT_SPRITE_URLS.elves_elven_sentinel,
  ironbreaker: UNIT_SPRITE_URLS.dwarves_ironbreaker,
};

export function getUnitSpriteUrl(unitType: UnitType, faction: FactionId): string {
  const key = `${faction}_${unitType}`;
  const exact = UNIT_SPRITE_URLS[key];
  if (exact) return exact;

  const uniqueFallback = UNIQUE_UNIT_FALLBACKS[unitType];
  if (uniqueFallback) return uniqueFallback;

  return UNIT_SPRITE_URLS[`${faction}_warrior`] ?? UNIT_SPRITE_URLS.humans_warrior;
}
